'use client';

import { useState, useTransition, useEffect, useActionState } from 'react';
import { submitReservation } from '../actions';

const initialState = {
  message: '',
  errors: {},
  success: false,
};

const PassengerInput = ({ index, passenger, updatePassenger, errors }) => (
  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t border-gray-200">
    <div>
      <label htmlFor={`name-${index}`} className="block text-sm font-medium text-gray-700 mb-1">Nome Completo do Passageiro {index + 1}</label>
      <input 
        type="text" 
        id={`name-${index}`} 
        name={`passengers[${index}][name]`}
        value={passenger.name}
        onChange={(e) => updatePassenger(index, 'name', e.target.value)}
        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition"
        required
      />
      {errors?.[`passengers.${index}.name`] && <p className="text-sm text-red-500 mt-1">{errors[`passengers.${index}.name`][0]}</p>}
    </div>
    <div>
      <label htmlFor={`cpf-${index}`} className="block text-sm font-medium text-gray-700 mb-1">CPF do Passageiro {index + 1}</label>
      <input 
        type="text" 
        id={`cpf-${index}`} 
        name={`passengers[${index}][cpf]`}
        value={passenger.cpf}
        onChange={(e) => updatePassenger(index, 'cpf', e.target.value)}
        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition"
        required
        pattern="\d{3}\.\d{3}\.\d{3}-\d{2}"
        placeholder="000.000.000-00"
      />
      {errors?.[`passengers.${index}.cpf`] && <p className="text-sm text-red-500 mt-1">{errors[`passengers.${index}.cpf`][0]}</p>}
    </div>
  </div>
);

export default function ReservationForm({ packageId, availability, price }: { packageId: string; availability: number; price: number }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formState, formAction] = useActionState(submitReservation, initialState);
  const [isPending, startTransition] = useTransition();
  
  const [step, setStep] = useState(1);
  const [numTravelers, setNumTravelers] = useState(1);
  const [passengers, setPassengers] = useState([{ name: '', cpf: '' }]);
  const [paymentMethod, setPaymentMethod] = useState('credit_card');

  const handleOpenModal = () => setIsModalOpen(true);
  const handleCloseModal = () => {
    setIsModalOpen(false);
    setStep(1);
    setPassengers([{ name: '', cpf: '' }]);
    setNumTravelers(1);
  };

  useEffect(() => {
    if (formState.success && isModalOpen) {
      const timer = setTimeout(() => handleCloseModal(), 5000);
      return () => clearTimeout(timer);
    }
  }, [formState.success, isModalOpen]);

  useEffect(() => {
    setPassengers(Array.from({ length: numTravelers }, () => ({ name: '', cpf: '' })));
  }, [numTravelers]);

  const updatePassenger = (index, field, value) => {
    const newPassengers = [...passengers];
    newPassengers[index][field] = value;
    setPassengers(newPassengers);
  };

  const goToNextStep = () => setStep(2);
  const goToPrevStep = () => setStep(1);

  const totalValue = price * numTravelers;

  return (
    <>
      <button
        onClick={handleOpenModal}
        className="w-full py-4 px-6 bg-green-500 text-white font-bold text-lg rounded-lg shadow-lg hover:bg-green-600 transition-all duration-300 transform hover:scale-105 disabled:bg-gray-400 disabled:cursor-not-allowed disabled:transform-none"
        disabled={availability <= 0}
      >
        {availability > 0 ? 'Quero Reservar!' : 'Esgotado'}
      </button>

      {isModalOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in"
          onClick={handleCloseModal}
        >
          <div 
            className="bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-auto relative transform transition-all animate-fade-in-up max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <button onClick={handleCloseModal} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 transition-colors z-20">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>

            {formState.success ? (
              <div className="p-8 text-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mx-auto text-green-500 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">Reserva Confirmada!</h2>
                <p className="text-gray-600 leading-relaxed">{formState.message}</p>
                <p className="text-sm text-gray-500 mt-4">Você será redirecionado em breve.</p>
              </div>
            ) : (
              <form action={(formData) => {
                  // Append dynamic data to formData before submitting
                  formData.append('numTravelers', numTravelers.toString());
                  formData.append('totalValue', totalValue.toString());
                  passengers.forEach((p, i) => {
                      formData.append(`passengers[${i}][name]`, p.name);
                      formData.append(`passengers[${i}][cpf]`, p.cpf);
                  });
                  startTransition(() => formAction(formData));
              }} className="p-8">
                <h2 className="text-2xl font-bold text-gray-800 text-center mb-2">Sua Reserva</h2>
                <p className="text-center text-gray-500 mb-6">Passo {step} de 2</p>

                <input type="hidden" name="packageId" value={packageId} />

                {/* Step 1: Passenger Details */}
                <div style={{ display: step === 1 ? 'block' : 'none' }} className="space-y-5 animate-fade-in">
                  <div>
                    <label htmlFor="numTravelers" className="block text-sm font-medium text-gray-700 mb-1">Quantos viajantes?</label>
                    <select 
                      id="numTravelers" 
                      name="numTravelers" 
                      value={numTravelers}
                      onChange={(e) => setNumTravelers(Number(e.target.value))}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition"
                    >
                      {Array.from({ length: availability }, (_, i) => i + 1).map(n => (
                        <option key={n} value={n}>{n} {n > 1 ? 'pessoas' : 'pessoa'}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-4">
                    {passengers.map((p, i) => (
                      <PassengerInput key={i} index={i} passenger={p} updatePassenger={updatePassenger} errors={formState.errors} />
                    ))}
                  </div>
                   {formState.message && !formState.success && step === 1 && <p className="text-sm text-red-500 text-center">{formState.message}</p>}
                  <button 
                    type="button"
                    onClick={goToNextStep}
                    className="w-full mt-4 py-3 px-6 bg-green-500 text-white font-bold rounded-lg shadow-md hover:bg-green-600 transition-all"
                  >
                    Continuar para o Pagamento
                  </button>
                </div>

                {/* Step 2: Payment Details */}
                <div style={{ display: step === 2 ? 'block' : 'none' }} className="space-y-5 animate-fade-in">
                   <div className="bg-slate-100 p-4 rounded-lg">
                        <h3 className="font-bold text-lg mb-2">Resumo do Pedido</h3>
                        <div className="flex justify-between"><p>Pacote:</p> <p className="font-semibold">{numTravelers}x {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(price)}</p></div>
                        <div className="flex justify-between text-xl font-bold mt-2 border-t pt-2"><p>Total:</p> <p>{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(totalValue)}</p></div>
                   </div>

                  <div>
                    <h3 className="font-semibold text-gray-800">Método de Pagamento</h3>
                    {/* Payment method selection can be added here */}
                  </div>

                  {formState.message && !formState.success && step === 2 && <p className="text-sm text-red-500 text-center">{formState.message}</p>}

                  <div className="flex gap-4">
                    <button 
                      type="button"
                      onClick={goToPrevStep}
                      className="w-full py-3 px-6 bg-gray-200 text-gray-700 font-bold rounded-lg hover:bg-gray-300 transition-all"
                    >
                      Voltar
                    </button>
                    <button 
                      type="submit" 
                      disabled={isPending}
                      className="w-full py-3 px-6 bg-green-500 text-white font-bold rounded-lg shadow-md hover:bg-green-600 transition-all disabled:bg-gray-400 disabled:cursor-wait"
                    >
                      {isPending ? 'Confirmando...' : 'Confirmar Reserva'}
                    </button>
                  </div>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </>
  );
}
