'use server';

import { createClient } from '@supabase/supabase-js';
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';
import { z } from 'zod';
import { revalidatePath } from 'next/cache';

// --- CLIENTE SUPABASE (PÚBLICO) ---
const createSupabaseClient = () => {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!supabaseUrl || !supabaseAnonKey) {
    throw new Error('Credenciais do Supabase não encontradas. Verifique as variáveis de ambiente.');
  }
  
  return createClient(supabaseUrl, supabaseAnonKey);
};

// --- AÇÕES DE BUSCA DE DADOS ---

export async function getPublicPackages() {
  try {
    const supabase = createSupabaseClient();
    const { data, error } = await supabase
      .from('viagens')
      .select('*')
      .eq('ativo', true)
      .order('destino', { ascending: true });

    if (error) throw error;

    return { packages: data };
  } catch (error) {
    console.error("Erro ao buscar pacotes públicos:", error);
    return { error: "Não foi possível carregar os pacotes." };
  }
}


export async function getPublicPackageById(id: string) {
  try {
    const supabase = createSupabaseClient();
    const { data, error } = await supabase
      .from('viagens')
      .select('*')
      .eq('id', id)
      .limit(1);

    if (error) throw error;

    if (!data || data.length === 0) {
        return { pkg: null, error: `Pacote com ID ${id} não encontrado.` };
    }

    return { pkg: data[0] };

  } catch (e) {
    console.error(`Erro ao buscar pacote por ID ${id}:`, e);
    return { pkg: null, error: "Falha ao buscar dados do pacote." };
  }
}

// --- AÇÕES DE FORMULÁRIO (MUTATIONS) ---

// Novo schema para o formulário de múltiplos passos
const CreateReservationSchema = z.object({
  packageId: z.string().uuid({ message: 'ID do pacote inválido.' }),
  numTravelers: z.coerce.number().int().min(1, { message: 'É necessário pelo menos 1 viajante.' }),
  totalValue: z.coerce.number().min(0, { message: 'Valor total inválido.' }),
  passengers: z.array(z.object({
    name: z.string().min(3, { message: 'O nome do passageiro deve ter pelo menos 3 caracteres.' }),
    // Basic CPF regex validation (format 000.000.000-00)
    cpf: z.string().regex(/^\d{3}\.\d{3}\.\d{3}-\d{2}$/, { message: 'CPF inválido. Use o formato XXX.XXX.XXX-XX.' }),
  })).min(1, { message: 'É necessário adicionar pelo menos um passageiro.' })
});


// Ação de reserva refatorada
export async function submitReservation(prevState: any, formData: FormData) {
    const cookieStore = cookies();
    const supabase = createRouteHandlerClient({ cookies: () => cookieStore });

    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return {
            message: 'Acesso negado. Por favor, faça login para continuar.',
            errors: {},
            success: false,
        };
    }
    
    // Extrair passageiros do formData
    const passengers = [];
    let i = 0;
    while (formData.has(`passengers[${i}][name]`)) {
        passengers.push({
            name: formData.get(`passengers[${i}][name]`),
            cpf: formData.get(`passengers[${i}][cpf]`),
        });
        i++;
    }

    const validatedFields = CreateReservationSchema.safeParse({
        packageId: formData.get('packageId'),
        numTravelers: formData.get('numTravelers'),
        totalValue: formData.get('totalValue'),
        passengers: passengers,
    });

    if (!validatedFields.success) {
        // Achatando os erros para um formato mais fácil de usar na UI
        const flattenedErrors = {};
        for (const issue of validatedFields.error.issues) {
            flattenedErrors[issue.path.join('.')] = issue.message;
        }

        return {
            message: 'Falha na validação. Por favor, verifique os campos.',
            errors: flattenedErrors,
            success: false,
        };
    }
    
    const { packageId, numTravelers, totalValue } = validatedFields.data;

    try {
        // **INÍCIO DA TRANSAÇÃO SIMULADA**
        // A lógica real do banco de dados será implementada aqui no próximo passo.
        
        console.log('--- Iniciando Simulação de Reserva ---');
        console.log('Usuário ID:', user.id);
        console.log('Pacote ID:', packageId);
        console.log('Número de Viajantes:', numTravelers);
        console.log('Valor Total:', totalValue);
        console.log('Passageiros:', JSON.stringify(validatedFields.data.passengers, null, 2));

        // 1. Simular verificação de disponibilidade
        console.log(`[SIMULAÇÃO] Verificando disponibilidade para ${numTravelers} vagas no pacote ${packageId}...`);
        // Lógica para buscar pkg.disponibilidade e comparar com numTravelers viria aqui.
        await new Promise(resolve => setTimeout(resolve, 500));

        // 2. Simular criação da reserva
        console.log('[SIMULAÇÃO] Criando registro na tabela `reservas`...');
        await new Promise(resolve => setTimeout(resolve, 500));
        
        // 3. Simular criação do pagamento
        console.log('[SIMULAÇÃO] Criando registro na tabela `pagamentos`...');
        await new Promise(resolve => setTimeout(resolve, 500));

        // 4. Simular atualização da disponibilidade
        console.log('[SIMULAÇÃO] Atualizando a disponibilidade na tabela `viagens`...');
        await new Promise(resolve => setTimeout(resolve, 500));
        
        console.log('--- Simulação de Reserva Concluída com Sucesso ---');
        // **FIM DA TRANSAÇÃO SIMULADA**

        // Revalidação do cache para atualizar a UI
        revalidatePath(`/packages/${packageId}`);
        revalidatePath('/my-trips');

        return {
            message: `Reserva para ${numTravelers} pessoa(s) confirmada com sucesso! Você já pode visualizá-la em "Minhas Viagens".`,
            errors: {},
            success: true,
        };

    } catch (e) {
        console.error("Erro ao processar reserva:", e);
        return {
            message: 'Ocorreu um erro inesperado no servidor. Tente novamente mais tarde.',
            errors: {},
            success: false,
        };
    }
}
